// Dictionary engine — no UI, no dependencies, works fully offline on the JSON
// under public/data/ (generated by scripts/build-data.mjs, see its header and
// public/data/dict/manifest.json).
//
// Data layout used here:
//   /data/dict/index-hanzi.json       { type, chars: { <simplifiedChar>: [shard] } }
//   /data/dict/index-hanzi-trad.json  same, keyed by traditional char
//   /data/dict/index-pinyin/<a-z>.json  { <tonelessKey>: [shard] }   (whole word)
//   /data/dict/index-english/<a-z>.json { <englishWord>: [shard] }
//   /data/dict/shards/NNN.json        [{ id, simp, trad, pinyin, pinyinNumeric, defs[] }]
//
// Shards are fetched lazily on first use and cached (a search touches 1 index
// file + the 1–n shards it points at, never all 115).
//
// Public API (all async):
//   search(query, { limit = 20 }) -> [{ id, simp, trad, pinyinTone, pinyinNum, defs }]
//       Detects hanzi (simp or trad), pinyin ("nǐ hǎo" | "ni3hao3" | "ni hao")
//       and english ("hello"); exact matches rank first.
//   lookup(word) -> entry | null          exact hanzi/pinyin word lookup
//   segment(text) -> string[]             longest-match word split (reader)
//   detectType(query) -> 'hanzi' | 'pinyin' | 'latin'
//   configure({ fetch })                  inject a fetch for Node/tests
//   resetCache()                          drop cached shards/indexes

import { pinyinToMarks, tonelessKey } from './pinyin.js';

const BASE = typeof document === 'undefined' ? '/data/dict' : new URL('data/dict', document.baseURI);

const HANZI_RE = /[\u3400-\u9fff\uf900-\ufaff]/;
const TONE_MARK_RE = /[āáǎàēéěèīíǐìōóǒòūúǔùǖǘǚǜ]/i;
const TONE_NUM_RE = /[a-zü][1-5]/i;
const LATIN_RE = /^[a-zü\s'1-5]+$/i;

let fetcher = null;
const cache = new Map();

/** Inject a fetch implementation (Node tests, workers). Clears the cache. */
export function configure(opts = {}) {
  if (typeof opts.fetch === 'function') fetcher = opts.fetch;
  resetCache();
}

/** Drop every cached index/shard (fetched again on next use). */
export function resetCache() {
  cache.clear();
}

function getJSON(rel) {
  const url = `${BASE}/${rel}`;
  let pending = cache.get(url);
  if (!pending) {
    pending = Promise.resolve()
      .then(() => (fetcher || globalThis.fetch)(url))
      .then((res) => {
        if (!res || res.ok === false) throw new Error(`dictionary: ${rel} -> ${res && res.status}`);
        return res.json();
      });
    cache.set(url, pending);
    pending.catch(() => cache.delete(url));
  }
  return pending;
}

const shardId = (n) => `shards/${String(n).padStart(3, '0')}.json`;
const letterOf = (s) => (s && /[a-z]/.test(s[0]) ? s[0] : null);

const loadShard = (id) => getJSON(shardId(id));
const loadHanziIndex = () => getJSON('index-hanzi.json');
const loadTradIndex = () => getJSON('index-hanzi-trad.json');
const loadPinyinIndex = (letter) => getJSON(`index-pinyin/${letter}.json`);
const loadEnglishIndex = (letter) => getJSON(`index-english/${letter}.json`);

async function shardsFor(ids) {
  const unique = [...new Set(ids || [])];
  const loaded = await Promise.all(unique.map(loadShard));
  return loaded.flat();
}

/** Candidate shard ids for a hanzi word, from both the simp and trad indices. */
async function hanziShards(word) {
  const ch = [...word][0];
  if (!ch) return [];
  const ids = [];
  for (const load of [loadHanziIndex, loadTradIndex]) {
    const idx = await load().catch(() => null);
    const list = idx && idx.chars && idx.chars[ch];
    if (list) ids.push(...list);
  }
  return ids;
}

// ---------------------------------------------------------------- detection

/** Coarse query type; `'latin'` still has to be told pinyin from english. */
export function detectType(query) {
  const q = String(query ?? '').trim();
  if (!q) return 'latin';
  if (HANZI_RE.test(q)) return 'hanzi';
  if (TONE_MARK_RE.test(q) || TONE_NUM_RE.test(q)) return 'pinyin';
  return 'latin';
}

/** Does the pinyin index know this (tone-less) latin query? */
async function isPinyin(q) {
  const key = tonelessKey(q);
  const letter = letterOf(key);
  if (!letter) return false;
  const idx = await loadPinyinIndex(letter).catch(() => null);
  if (!idx) return false;
  if (idx[key]) return true;
  return Object.keys(idx).some((k) => k.startsWith(key));
}

// ---------------------------------------------------------------- search

const toResult = (e) => ({
  id: e.id,
  simp: e.simp,
  trad: e.trad,
  pinyinTone: e.pinyin,
  pinyinNum: e.pinyinNumeric,
  defs: e.defs,
});

function rank(list, limit) {
  const seen = new Set();
  return list
    .filter((h) => (seen.has(h.e.id) ? false : seen.add(h.e.id)))
    .sort((a, b) => b.score - a.score || a.e.simp.length - b.e.simp.length)
    .slice(0, Math.max(0, limit))
    .map((h) => toResult(h.e));
}

async function searchHanzi(q) {
  const entries = await shardsFor(await hanziShards(q));
  const out = [];
  for (const e of entries) {
    const exact = e.simp === q || e.trad === q;
    const prefix = !exact && (e.simp.startsWith(q) || e.trad.startsWith(q));
    const contains = !exact && !prefix && (e.simp.includes(q) || e.trad.includes(q));
    if (exact) out.push({ e, score: 100 });
    else if (prefix) out.push({ e, score: 70 - Math.min(30, e.simp.length - q.length) });
    else if (contains) out.push({ e, score: 40 - Math.min(20, e.simp.length - q.length) });
  }
  return out;
}

async function searchPinyin(q) {
  const key = tonelessKey(q);
  const letter = letterOf(key);
  if (!letter) return [];
  const idx = await loadPinyinIndex(letter).catch(() => null);
  if (!idx) return [];

  const ids = [];
  for (const [k, list] of Object.entries(idx)) {
    if (k === key) ids.push(...list);
    else if (ids.length < 200 && k.startsWith(key)) ids.push(...list);
  }
  const entries = await shardsFor(ids);
  const out = [];
  for (const e of entries) {
    const ek = tonelessKey(e.pinyinNumeric || '');
    if (ek === key) out.push({ e, score: 100 });
    else if (ek.startsWith(key)) out.push({ e, score: 70 - Math.min(30, ek.length - key.length) });
  }
  return out;
}

async function searchEnglish(q) {
  const words = q.toLowerCase().match(/[a-z][a-z'-]*/g) || [];
  if (!words.length) return [];
  const primary = words[0];
  const letter = letterOf(primary);
  if (!letter) return [];
  const idx = await loadEnglishIndex(letter).catch(() => null);
  if (!idx) return [];

  const ids = [];
  const keys = Object.keys(idx);
  for (const k of keys) {
    if (k === primary) ids.push(...idx[k]);
    else if (ids.length < 200 && k.startsWith(primary)) ids.push(...idx[k]);
  }
  const entries = await shardsFor(ids);
  const wanted = new Set(words);
  const out = [];
  for (const e of entries) {
    let best = 0;
    for (const def of e.defs) {
      const tokens = (def.toLowerCase().match(/[a-z][a-z'-]*/g) || []);
      for (const w of wanted) {
        const at = tokens.indexOf(w);
        if (at === -1) continue;
        // Earlier in the definition wins; a whole-definition hit wins more.
        const score = 100 - at * 5 + (tokens.length === 1 ? 20 : 0);
        if (score > best) best = score;
      }
    }
    if (best > 0) out.push({ e, score: best });
  }
  return out;
}

/**
 * Search the dictionary. Query type is auto-detected.
 * @param {string} query
 * @param {{ limit?: number }} [opts]
 * @returns {Promise<Array<{id:number,simp:string,trad:string,pinyinTone:string,pinyinNum:string,defs:string[]}>>}
 */
export async function search(query, { limit = 20 } = {}) {
  const q = String(query ?? '').trim();
  if (!q) return [];
  const type = detectType(q);
  let hits;
  if (type === 'hanzi') hits = await searchHanzi(q);
  else if (type === 'pinyin' || (await isPinyin(q))) hits = await searchPinyin(q);
  else hits = await searchEnglish(q);
  return rank(hits, limit);
}

// ---------------------------------------------------------------- lookup

/** Exact lookup by hanzi (simp or trad) or by pinyin word. */
export async function lookup(word) {
  const q = String(word ?? '').trim();
  if (!q) return null;
  if (detectType(q) === 'hanzi') {
    const entries = await shardsFor(await hanziShards(q));
    const hit = entries.find((e) => e.simp === q || e.trad === q);
    return hit ? toResult(hit) : null;
  }
  const results = await search(q, { limit: 50 });
  return results[0] || null;
}

/** Exact hanzi match against the entry's own shard set (segment helper). */
async function exactHanzi(word) {
  const entries = await shardsFor(await hanziShards(word));
  return entries.find((e) => e.simp === word || e.trad === word) || null;
}

// ---------------------------------------------------------------- segment

const MAX_WORD = 8;

/**
 * Split text into dictionary words using longest-match, for the reader.
 * Hanzi runs are matched against the dictionary; everything else (latin,
 * digits, punctuation, spaces) is passed through as its own chunk.
 * @returns {Promise<string[]>}
 */
export async function segment(text) {
  const s = String(text ?? '');
  const out = [];
  let buf = '';
  const flush = () => {
    if (buf) { out.push(buf); buf = ''; }
  };
  for (let i = 0; i < s.length;) {
    const ch = s[i];
    if (!HANZI_RE.test(ch)) { buf += ch; i += 1; continue; }
    flush();
    let matched = null;
    for (let len = Math.min(MAX_WORD, s.length - i); len >= 2; len--) {
      const cand = s.slice(i, i + len);
      if (![...cand].every((c) => HANZI_RE.test(c))) continue;
      matched = await exactHanzi(cand);
      if (matched) { out.push(matched.simp); i += len; break; }
    }
    if (!matched) { out.push(ch); i += 1; }
  }
  flush();
  return out;
}

/** Tone-marked display form for an entry (or any numbered pinyin string). */
export function withToneMarks(pinyin) {
  return pinyinToMarks(pinyin || '');
}